// Initialize empty array for hotel IDs
let hotelIds = [];

// Loop through all incoming items from previous node
for (const item of $input.all()) {

  // Parse the JSON string from the "data" field
  const parsed = JSON.parse(item.json.data);

  // Ensure data exists and is an array
  if (parsed.data && Array.isArray(parsed.data)) {

    // Extract each hotelId
    for (const hotel of parsed.data) {
      if (hotel.hotelId) {
        hotelIds.push(hotel.hotelId);
      }
    }
  }
}

// Function to chunk array into batches of a given size
function chunkArray(arr, size) {
  const result = [];
  for (let i = 0; i < arr.length; i += size) {
    result.push(arr.slice(i, i + size));
  }
  return result;
}

// Split hotelIds into batches of 100
const batches = chunkArray(hotelIds, 50);

// Return each batch as a separate item for n8n to loop through
return batches.map(batch => ({
  json: { hotelIds: batch }
}));

return $input.all().map(item => {
  const hotelName = item.json.hotelName || '';
  const cityCode = item.json.cityCode || '';

  // Build search links
  const googleLink = `https://www.google.com/search?q=${encodeURIComponent(hotelName + ' ' + cityCode)}`;
  const bookingLink = `https://www.booking.com/searchresults.html?ss=${encodeURIComponent(hotelName + ' ' + cityCode)}`;

  // Return full original data + new fields
  return {
    json: {
      ...item.json,
      googleSearchLink: googleLink,
      bookingSearchLink: bookingLink
    }
  };
});

